SELECT id, customer_id, created_at, coupon_codes, items, ship_to, AGGREGATE(items, CAST(0 AS DOUBLE), (acc, item) -> acc + item.qty * item.price, acc -> ROUND(acc, 2)) AS items_total, EXISTS(coupon_codes, c -> c LIKE 'W%') AS has_welcome_code, TRANSFORM(FILTER(items, item -> item.promo IS NOT NULL), item -> STRUCT(item.product_id AS pid, ROUND(item.price * 0.9, 2) AS discounted_price)) AS promo_lines FROM carts
